import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String data = scanner.nextLine();
        char firstChar = data.charAt(0);
        String restOfString = data.substring(1).replace("dot", ".");
        String fullString = firstChar + restOfString;
        if (fullString.charAt(fullString.length() - 1) == '.') {
            fullString = fullString.substring(0, fullString.length() - 1) + "dot";
        }
        firstChar = fullString.charAt(0);
        String restString = fullString.substring(1).replaceFirst("at", "@");
        if (restString.endsWith("@")) {
            restString = restString.substring(0, restString.length() - 1) + "at";
        }
        System.out.println(firstChar + restString);
    }
}
